import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { toast } from 'sonner'
import type { Objective, ObjectiveTab } from '@/entities/objective/types'
import { CheckCircle2, Circle } from 'lucide-react'

type Props = { objective: Objective; onTabChange: (tab: ObjectiveTab) => void }

export function CompleteTab({ objective, onTabChange: _onTabChange }: Props) {
  const navigate = useNavigate()
  const [confirmed, setConfirmed] = useState(false)

  const participantConfirmations = objective.participants.filter((p) => p.role !== 'viewer').map((p) => ({ ...p, confirmed: p.role === 'owner' }))

  const handleComplete = () => {
    if (!confirmed) return
    toast.success('Objective marked as complete!')
    navigate(-1)
  }

  return (
    <div className="p-6 max-w-2xl mx-auto">
      <div className="flex flex-col gap-4">
        <div className="bg-surface rounded-xl border border-border p-6">
          <h3 className="font-medium mb-4">Participant confirmations</h3>
          <div className="flex flex-col gap-3">
            {participantConfirmations.map((p) => (
              <div key={p.userId} className="flex items-center gap-3">
                {p.confirmed ? <CheckCircle2 size={16} className="text-success" /> : <Circle size={16} className="text-muted-foreground" />}
                <span className="text-sm">{p.displayName}</span>
                <span className="text-xs text-muted-foreground capitalize ml-auto">{p.role}</span>
              </div>
            ))}
          </div>
        </div>
        <div className="bg-surface rounded-xl border border-border p-6">
          <h3 className="font-medium mb-4">Complete objective</h3>
          <p className="text-sm text-muted-foreground mb-4">Once completed, value will be distributed to contributors according to the assigned amounts. This action triggers payment and cannot be undone.</p>
          <label className="flex items-start gap-3 cursor-pointer mb-4">
            <input type="checkbox" checked={confirmed} onChange={(e) => setConfirmed(e.target.checked)} className="mt-0.5 rounded" />
            <span className="text-sm">I confirm all deliverables have been met and evaluations are complete</span>
          </label>
          <button onClick={handleComplete} disabled={!confirmed} className="bg-success text-white px-6 py-2.5 rounded-lg text-sm font-medium hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed">
            Mark objective complete
          </button>
        </div>
      </div>
    </div>
  )
}
